CREATE INDEX "Course_collegeId_idx" ON public."Course" USING btree ("collegeId");

CREATE INDEX "Course_shared_in_idx" ON public."Course" USING btree (shared_in) WHERE (shared_in = 1);

CREATE INDEX crse_instrctr_rel_t_college_id_idx ON public.crse_instrctr_rel_t USING btree (college_id);

CREATE UNIQUE INDEX crse_instrctr_rel_t_course_id_user_id_key ON public.crse_instrctr_rel_t USING btree (course_id, user_id);

